import {readFileSync,writeFileSync} from 'node:fs';
import {resolve} from 'node:path';
import {fileURLToPath} from 'node:url';

// Compile existing ESM implementation for ordinary <script defer> loading.
// Classic scripts can load from file:// where browsers may block local ESM imports.
const root=resolve(fileURLToPath(new URL('..',import.meta.url)));
const sources=['sim/life.mjs','sim/life-train.mjs','life-ui.mjs'];
const chunks=sources.map(path=>{
 let source=readFileSync(resolve(root,path),'utf8');
 source=source.replace(/^import \{[^\n]*\} from ['"][^'"\n]+['"];?[ \t]*\r?\n/gm,'');
 source=source.replace(/^export (?=(?:const|let|function|class)\b)/gm,'');
 if(/^(?:import|export)\b/m.test(source))throw Error('Unsupported module declaration: '+path);
 return '// SOURCE: '+path+'\n'+source;
});
const bundle='/* GENERATED by node scripts/build-life-bundle.mjs. Do not edit by hand. */\n(function(){\n\'use strict\';\n'+chunks.join('\n\n')+'\n})();\n';
const output=resolve(root,'life.bundle.js');
if(process.argv.includes('--check')){
 const actual=readFileSync(output,'utf8');
 if(actual!==bundle)throw Error('life.bundle.js is stale; run npm run build:life');
 console.log('PASS life.bundle.js matches ESM source byte-for-byte after import/export transformation');
}else{
 writeFileSync(output,bundle);
 console.log('Generated '+output+' ('+Buffer.byteLength(bundle)+' bytes)');
}
